using Microsoft.EntityFrameworkCore;using PokemonMvc.Data;var b=WebApplication.CreateBuilder(args);b.Services.AddControllersWithViews();b.Services.AddDbContext<PokemonContext>(o=>o.UseSqlite(b.Configuration.GetConnectionString("PokemonContext")));var app=b.Build();using(var s=app.Services.CreateScope()){var db=s.ServiceProvider.GetRequiredService<PokemonContext>();db.Database.EnsureCreated();SeedData.Initialize(db);}app.UseHttpsRedirection();app.UseStaticFiles();app.UseRouting();app.MapControllerRoute("default","{controller=Home}/{action=Index}/{id?}");app.Run();